/* Kramavriddhi Learn arcade (S6): small games played as game breaks, picked from the learner's skills.
   type 'swipe': each item goes left or right before the timer ends. Items: t (situation), a ('l' or 'r'), why; te = Telugu. */
window.KV_ARCADE = [
  {"id":"batchstream","type":"swipe","name":"Batch or Stream?","icon":"🔀","skills":["de","az","gcp","aws","snow"],"intro":"Swipe each situation: is it processed in scheduled chunks (Batch) or event by event as it happens (Stream)?","left":"Batch","right":"Stream","secs":7,"rounds":6,"te":{"name":"Batch లేదా Stream?","intro":"ప్రతి situation ని swipe చేయండి: data ని schedule ప్రకారం గుంపులుగా (Batch) process చేస్తారా, లేదా ప్రతి event వచ్చిన వెంటనే (Stream) process చేస్తారా?","left":"Batch","right":"Stream"},"items":[{"t":"Monthly salary slips for 5,000 employees","a":"l","why":"Salaries are calculated once a month for everyone together.","te":{"t":"5,000 మంది ఉద్యోగులకు నెలవారీ salary slips","why":"Salaries నెలకు ఒకసారి అందరికీ కలిపి లెక్కిస్తారు."}},{"t":"Card fraud alert within seconds of a payment","a":"r","why":"Fraud must be caught while the payment is happening, so each event is checked at once.","te":{"t":"Payment జరిగిన seconds లోనే card fraud alert","why":"Payment జరుగుతుండగానే fraud పట్టుకోవాలి, కాబట్టి ప్రతి event వెంటనే check చేస్తారు."}},{"t":"Live cricket score on an app, ball by ball","a":"r","why":"Every ball is an event that must show immediately.","te":{"t":"App లో ball by ball live cricket score","why":"ప్రతి ball ఒక event, అది వెంటనే కనిపించాలి."}},{"t":"Nightly copy of the day’s sales into the warehouse","a":"l","why":"A scheduled job moves the whole day’s data in one chunk at night.","te":{"t":"రోజు sales ని రాత్రి warehouse లోకి copy చేయడం","why":"Schedule చేసిన job రోజంతా data ని రాత్రి ఒకేసారి తరలిస్తుంది."}},{"t":"Delivery rider’s location moving on the map","a":"r","why":"GPS updates arrive every few seconds and the map follows them live.","te":{"t":"Map మీద delivery rider location కదలడం","why":"GPS updates ప్రతి కొన్ని seconds కి వస్తాయి, map వాటిని live గా చూపిస్తుంది."}},{"t":"Yearly tax summary for every customer","a":"l","why":"It is made once a year from a full year of data.","te":{"t":"ప్రతి customer కి సంవత్సర tax summary","why":"ఇది సంవత్సరం మొత్తం data నుంచి ఏడాదికి ఒకసారి తయారవుతుంది."}},{"t":"Factory machine alarm when temperature jumps","a":"r","why":"Sensor readings are checked as they arrive so the alarm can ring at once.","te":{"t":"Temperature పెరిగితే factory machine alarm","why":"Sensor readings వచ్చిన వెంటనే check చేస్తారు, అందుకే alarm వెంటనే మోగుతుంది."}},{"t":"Weekly email of the top 10 products","a":"l","why":"One report a week from a week of data is a scheduled batch job.","te":{"t":"వారానికి ఒకసారి top 10 products email","why":"వారం data నుంచి వారానికి ఒక report: ఇది schedule చేసిన batch job."}},{"t":"UPI “payment received” message on the shop speaker","a":"r","why":"Each payment triggers its own message right away.","te":{"t":"shop speaker లో UPI “payment received” సందేశం","why":"ప్రతి payment వెంటనే తన సొంత సందేశాన్ని పంపుతుంది."}},{"t":"End-of-day attendance report at 6 PM","a":"l","why":"The report is built once, at a fixed time, from the whole day.","te":{"t":"సాయంత్రం 6 కి రోజు చివరి attendance report","why":"రోజు మొత్తం data నుంచి నిర్ణీత సమయానికి ఒకసారి report తయారవుతుంది."}},{"t":"Live counter of visitors on a website right now","a":"r","why":"Each page visit is counted as it happens.","te":{"t":"ఇప్పుడు website లో ఎంతమంది ఉన్నారో live counter","why":"ప్రతి page visit జరిగిన వెంటనే లెక్కిస్తారు."}},{"t":"Re-loading last year’s data into a new dashboard","a":"l","why":"Old data is loaded once, in big chunks; nothing needs to be instant.","te":{"t":"గత సంవత్సరం data ని కొత్త dashboard లోకి మళ్ళీ load చేయడం","why":"పాత data ఒకేసారి పెద్ద గుంపులుగా load అవుతుంది; ఏదీ వెంటనే అవసరం లేదు."}},{"t":"Traffic jam warning on a maps app as vehicles slow down","a":"r","why":"Each vehicle's speed arrives as it moves, so the jam is spotted as it forms.","te":{"t":"Vehicles నెమ్మదించగానే maps app లో traffic jam warning","why":"ప్రతి vehicle speed కదులుతున్నప్పుడే వస్తుంది, కాబట్టి jam ఏర్పడుతుండగానే తెలుస్తుంది."}},{"t":"Monthly electricity bill for every house","a":"l","why":"Meter readings for the month are processed together to make the bills.","te":{"t":"ప్రతి ఇంటికి నెలవారీ కరెంటు bill","why":"నెల meter readings ని కలిపి process చేసి bills తయారు చేస్తారు."}},{"t":"Share price ticker moving on a trading app","a":"r","why":"Every trade changes the price, and the app shows it as it happens.","te":{"t":"Trading app లో share price ticker కదలడం","why":"ప్రతి trade price ని మారుస్తుంది, app దాన్ని జరిగిన వెంటనే చూపిస్తుంది."}},{"t":"Backing up all college records every Sunday night","a":"l","why":"A weekly scheduled backup copies everything in one run.","te":{"t":"ప్రతి ఆదివారం రాత్రి college records అన్నీ backup చేయడం","why":"వారానికి ఒకసారి schedule చేసిన backup అన్నిటినీ ఒకే run లో copy చేస్తుంది."}},{"t":"Marks memos for all students after exams finish","a":"l","why":"Results are computed together for everyone after all exams are done.","te":{"t":"Exams అయిపోయాక అందరు students కి marks memos","why":"అన్ని exams అయ్యాక అందరి results కలిపి లెక్కిస్తారు."}},{"t":"WhatsApp message appearing the moment a friend sends it","a":"r","why":"Each message is delivered as its own event, at once.","te":{"t":"Friend పంపిన వెంటనే WhatsApp message కనిపించడం","why":"ప్రతి message ఒక event, అది వెంటనే చేరుతుంది."}},{"t":"Bank’s monthly account statement PDF","a":"l","why":"A month of transactions is collected and made into one statement on a schedule.","te":{"t":"Bank నుంచి నెలవారీ account statement PDF","why":"నెల transactions అన్నీ కలిపి schedule ప్రకారం ఒక statement తయారవుతుంది."}},{"t":"Train running status updating as it passes stations","a":"r","why":"Each station crossing is an event shown to passengers as it happens.","te":{"t":"Train stations దాటుతున్న కొద్దీ running status మారడం","why":"ప్రతి station దాటడం ఒక event, ప్రయాణికులకు వెంటనే కనిపిస్తుంది."}}]},
  {"id":"bouncer","type":"swipe","name":"Firewall Bouncer","icon":"🚪","skills":["aws","gcp","az","rh","lx"],"intro":"You guard a web server. Read the rules, then swipe each visitor: Block (left) or Allow (right). Anything the rules do not allow is blocked.","rules":["HTTPS (port 443) and HTTP (port 80) from anyone","SSH (port 22) only from the office IP 203.0.113.10","Everything else: blocked"],"left":"Block","right":"Allow","secs":10,"rounds":6,"te":{"name":"Firewall Bouncer","intro":"మీరు ఒక web server కి కాపలా. Rules చదివి, ప్రతి visitor ని swipe చేయండి: Block (ఎడమ) లేదా Allow (కుడి). Rules లో allow చేయనిది ఏదైనా block అవుతుంది.","rules":["HTTPS (port 443), HTTP (port 80): ఎవరి నుంచైనా","SSH (port 22): office IP 203.0.113.10 నుంచి మాత్రమే","మిగతా అన్నీ: block"],"left":"Block","right":"Allow"},"items":[{"t":"HTTPS (443) from a customer’s phone in Pune","a":"r","why":"HTTPS on 443 is allowed from anyone, so customers can open the site.","te":{"t":"Pune లోని customer phone నుంచి HTTPS (443)","why":"443 మీద HTTPS ఎవరి నుంచైనా allow, అందుకే customers site తెరవగలరు."}},{"t":"SSH (22) from the office IP 203.0.113.10","a":"r","why":"SSH is allowed only from the office IP, and this is that IP.","te":{"t":"Office IP 203.0.113.10 నుంచి SSH (22)","why":"SSH office IP నుంచి మాత్రమే allow, ఇది అదే IP."}},{"t":"SSH (22) from an unknown IP 198.51.100.7","a":"l","why":"SSH is allowed only from the office IP. Open SSH is how attackers try to log in.","te":{"t":"తెలియని IP 198.51.100.7 నుంచి SSH (22)","why":"SSH office IP నుంచి మాత్రమే allow. బయటకు తెరిచిన SSH ద్వారానే attackers login కి ప్రయత్నిస్తారు."}},{"t":"HTTP (80) from a student’s laptop in Guntur","a":"r","why":"HTTP on 80 is allowed from anyone.","te":{"t":"Guntur లోని student laptop నుంచి HTTP (80)","why":"80 మీద HTTP ఎవరి నుంచైనా allow."}},{"t":"MySQL database (3306) from the internet","a":"l","why":"Port 3306 is not in the rules. A database should never be open to the whole internet.","te":{"t":"Internet నుంచి MySQL database (3306)","why":"3306 port rules లో లేదు. Database ని ఎప్పుడూ internet మొత్తానికి తెరవకూడదు."}},{"t":"Remote Desktop (3389) from an unknown IP","a":"l","why":"Port 3389 is not allowed, so it is blocked.","te":{"t":"తెలియని IP నుంచి Remote Desktop (3389)","why":"3389 port allow కాలేదు, అందుకే block."}},{"t":"HTTPS (443) from a bot in another country","a":"r","why":"The rule allows HTTPS from anyone. A firewall only checks port and IP, so the web app behind that open port must still be safe.","te":{"t":"వేరే దేశంలోని bot నుంచి HTTPS (443)","why":"Rule HTTPS ని ఎవరి నుంచైనా allow చేస్తుంది. Firewall port, IP మాత్రమే చూస్తుంది, కాబట్టి ఆ open port వెనుక ఉన్న web app కూడా safe గా ఉండాలి."}},{"t":"Port 8080 from the office IP 203.0.113.10","a":"l","why":"Only SSH is allowed from the office IP. Port 8080 is in no rule.","te":{"t":"Office IP 203.0.113.10 నుంచి port 8080","why":"Office IP నుంచి SSH మాత్రమే allow. 8080 port ఏ rule లోనూ లేదు."}},{"t":"SSH (22) from the office IP 203.0.113.11","a":"l","why":"Close, but not the same IP. Only 203.0.113.10 may use SSH.","te":{"t":"Office IP 203.0.113.11 నుంచి SSH (22)","why":"దగ్గరగా ఉంది కానీ అదే IP కాదు. 203.0.113.10 కి మాత్రమే SSH allow."}},{"t":"HTTP (80) from the office IP 203.0.113.10","a":"r","why":"HTTP is allowed from anyone, and that includes the office.","te":{"t":"Office IP 203.0.113.10 నుంచి HTTP (80)","why":"HTTP ఎవరి నుంచైనా allow, office కూడా అందులో ఉంది."}},{"t":"Redis cache (6379) from the internet","a":"l","why":"Port 6379 is not in the rules, so it is blocked.","te":{"t":"Internet నుంచి Redis cache (6379)","why":"6379 port rules లో లేదు, అందుకే block."}},{"t":"HTTPS (443) from a delivery partner’s server","a":"r","why":"HTTPS is allowed from anyone.","te":{"t":"Delivery partner server నుంచి HTTPS (443)","why":"HTTPS ఎవరి నుంచైనా allow."}},{"t":"Telnet (23) from the office IP 203.0.113.10","a":"l","why":"Only SSH is allowed from the office IP. Telnet sends passwords as plain text, so keep it closed.","te":{"t":"Office IP 203.0.113.10 నుంచి Telnet (23)","why":"Office IP నుంచి SSH మాత్రమే allow. Telnet passwords ని plain text లో పంపుతుంది, కాబట్టి దాన్ని closed ఉంచండి."}},{"t":"FTP (21) from the internet","a":"l","why":"Port 21 is in no rule, so it is blocked. Open only the ports you need.","te":{"t":"Internet నుంచి FTP (21)","why":"21 port ఏ rule లోనూ లేదు, అందుకే block. అవసరమైన ports మాత్రమే తెరవండి."}},{"t":"SSH (22) from an admin’s home Wi-Fi, IP 192.0.2.55","a":"l","why":"SSH works only from the office IP 203.0.113.10. Even your own admin must follow the rule.","te":{"t":"Admin ఇంటి Wi-Fi, IP 192.0.2.55 నుంచి SSH (22)","why":"SSH office IP 203.0.113.10 నుంచి మాత్రమే. మీ admin అయినా rule పాటించాలి."}},{"t":"HTTP (80) from a search engine crawler","a":"r","why":"HTTP on 80 is allowed from anyone, so crawlers can read the site.","te":{"t":"Search engine crawler నుంచి HTTP (80)","why":"80 మీద HTTP ఎవరి నుంచైనా allow, అందుకే crawlers site చదవగలవు."}}]},
  {"id":"billshock","type":"tapset","name":"Bill Shock Hunter","icon":"💸","skills":["aws","gcp","az"],"intro":"Your practice account is still open. Tap every item that still costs money, then press Check. Free items stay untapped.","ask":"Tap everything that still costs money","secs":50,"te":{"name":"Bill Shock Hunter","intro":"మీ practice account ఇంకా open గా ఉంది. ఇంకా ఖర్చు అవుతున్న ప్రతి item ని tap చేసి, Check నొక్కండి. ఉచితమైనవి tap చేయకండి.","ask":"ఇంకా ఖర్చు అవుతున్నవన్నీ tap చేయండి","legend":"ఆకుపచ్చ అంచు = ఇంకా ఖర్చు అవుతోంది. ప్రతి tile కింద ఉన్న line చదవండి."},"scenes":[{"skill":"aws","title":"AWS account after a practice lab","te_title":"Practice lab తర్వాత AWS account","tiles":[{"t":"Running EC2 instance","on":true,"why":"A running instance is billed while it runs.","te":{"t":"Running EC2 instance","why":"Run అవుతున్నంత సేపు instance కి bill వస్తుంది."}},{"t":"EBS volume left after deleting the test server","on":true,"why":"EBS volumes are billed for the storage until you delete them.","te":{"t":"Test server delete చేశాక మిగిలిన EBS volume","why":"EBS volumes ని delete చేసే వరకు storage కి bill వస్తుంది."}},{"t":"NAT gateway left running","on":true,"why":"A NAT gateway is billed for every hour it exists.","te":{"t":"On లో వదిలేసిన NAT gateway","why":"NAT gateway ఉన్న ప్రతి గంటకూ bill వస్తుంది."}},{"t":"Lots of old log files in S3","on":true,"why":"S3 bills for the data you store.","te":{"t":"S3 లో చాలా పాత log files","why":"మీరు store చేసిన data కి S3 bill వేస్తుంది."}},{"t":"IAM user with no access keys","on":false,"why":"IAM itself has no extra charge.","te":{"t":"Access keys లేని IAM user","why":"IAM కి ప్రత్యేకంగా ఛార్జ్ లేదు."}},{"t":"Security group","on":false,"why":"Security groups are free; they are only rules.","te":{"t":"Security group","why":"Security groups ఉచితం; అవి rules మాత్రమే."}},{"t":"Empty S3 bucket","on":false,"why":"An empty bucket stores no data, so there is no storage charge.","te":{"t":"ఖాళీ S3 bucket","why":"ఖాళీ bucket లో data లేదు, కాబట్టి storage ఛార్జ్ లేదు."}},{"t":"VPC with only subnets and route tables","on":false,"why":"The VPC, subnets and route tables themselves are free.","te":{"t":"Subnets, route tables మాత్రమే ఉన్న VPC","why":"VPC, subnets, route tables కి ఛార్జ్ లేదు."}}]},{"skill":"gcp","title":"Google Cloud project after a practice lab","te_title":"Practice lab తర్వాత Google Cloud project","tiles":[{"t":"Running Compute Engine VM","on":true,"why":"A running VM is billed for its vCPUs and memory.","te":{"t":"Run అవుతున్న Compute Engine VM","why":"Run అవుతున్న VM కి vCPUs, memory కోసం bill వస్తుంది."}},{"t":"Persistent disk of a stopped VM","on":true,"why":"Stopping a VM does not delete its disk, and the disk is still billed.","te":{"t":"ఆపేసిన VM యొక్క persistent disk","why":"VM ని ఆపినా disk delete అవ్వదు, disk కి bill వస్తూనే ఉంటుంది."}},{"t":"Static external IP address not used by any VM","on":true,"why":"A reserved static IP that is not in use is billed.","te":{"t":"ఏ VM కీ వాడని static external IP","why":"వాడని reserved static IP కి bill వస్తుంది."}},{"t":"BigQuery tables full of data","on":true,"why":"BigQuery bills for the data you store.","te":{"t":"Data ఎక్కువగా ఉన్న BigQuery tables","why":"Store చేసిన data కి BigQuery bill వేస్తుంది."}},{"t":"IAM role given to a teammate","on":false,"why":"IAM roles and permissions are free.","te":{"t":"Teammate కి ఇచ్చిన IAM role","why":"IAM roles, permissions ఉచితం."}},{"t":"VPC firewall rule","on":false,"why":"Firewall rules themselves are free.","te":{"t":"VPC firewall rule","why":"Firewall rules కి ఛార్జ్ లేదు."}},{"t":"Empty Cloud Storage bucket","on":false,"why":"An empty bucket stores no data, so there is no storage charge.","te":{"t":"ఖాళీ Cloud Storage bucket","why":"ఖాళీ bucket లో data లేదు, కాబట్టి storage ఛార్జ్ లేదు."}},{"t":"Stopped VM’s CPU and memory","on":false,"why":"A stopped VM is not billed for vCPUs and memory, only for things like its disks.","te":{"t":"ఆపేసిన VM యొక్క CPU, memory","why":"ఆపేసిన VM కి vCPUs, memory కోసం bill ఉండదు; disks లాంటివాటికి మాత్రమే."}}]},{"skill":"az","title":"Azure subscription after a practice lab","te_title":"Practice lab తర్వాత Azure subscription","tiles":[{"t":"Running virtual machine","on":true,"why":"A running VM is billed for compute while it runs.","te":{"t":"Run అవుతున్న virtual machine","why":"Run అవుతున్నంత సేపు VM కి compute bill వస్తుంది."}},{"t":"Managed disk of a stopped (deallocated) VM","on":true,"why":"Deallocating stops compute charges, but the disk is still billed.","te":{"t":"ఆపేసిన (deallocated) VM యొక్క managed disk","why":"Deallocate చేస్తే compute ఛార్జ్ ఆగుతుంది, కానీ disk కి bill వస్తుంది."}},{"t":"Storage account full of blobs","on":true,"why":"Blob storage is billed for the data you keep.","te":{"t":"Blobs ఎక్కువగా ఉన్న storage account","why":"ఉంచిన data కి Blob storage bill వేస్తుంది."}},{"t":"Standard public IP address not attached to anything","on":true,"why":"A Standard public IP is billed even when it is not attached.","te":{"t":"దేనికీ attach చేయని Standard public IP","why":"Standard public IP attach చేయకపోయినా bill వస్తుంది."}},{"t":"Empty resource group","on":false,"why":"A resource group is only a folder; it has no charge.","te":{"t":"ఖాళీ resource group","why":"Resource group ఒక folder మాత్రమే; దానికి ఛార్జ్ లేదు."}},{"t":"Network security group","on":false,"why":"NSGs are rules and have no charge.","te":{"t":"Network security group","why":"NSGs rules మాత్రమే, ఛార్జ్ లేదు."}},{"t":"Virtual network with two subnets","on":false,"why":"A virtual network and its subnets are free.","te":{"t":"రెండు subnets ఉన్న virtual network","why":"Virtual network, దాని subnets ఉచితం."}},{"t":"Compute of a stopped (deallocated) VM","on":false,"why":"After deallocation you do not pay for the VM’s compute.","te":{"t":"ఆపేసిన (deallocated) VM యొక్క compute","why":"Deallocate చేశాక VM compute కి డబ్బు కట్టనక్కర్లేదు."}}]}],"legend":"Green border = it still costs money. Read the line under each tile."},
  {"id":"detective","type":"chain","name":"Why can’t I open it?","icon":"🕵️","skills":["rh","lx","dk"],"intro":"A new web server does not open in the browser. Be the detective: at each step pick the right check and find every problem.","te":{"name":"ఎందుకు తెరుచుకోవట్లేదు?","intro":"కొత్త web server browser లో తెరుచుకోవట్లేదు. Detective లా ప్రతి step లో సరైన check ఎంచుకుని, అన్ని సమస్యలు కనిపెట్టండి."},"cases":[{"skill":"rh","title":"Asha’s Apache web server on RHEL","te_title":"RHEL మీద ఆశా Apache web server","steps":[{"q":"First suspect: is the web server software even installed?","a":"`dnf list installed httpd`","w":["`hostnamectl`","`cat /etc/redhat-release`"],"clue":"httpd is installed. ✔ Not the problem.","te":{"q":"మొదటి అనుమానం: web server software install అయి ఉందా?","clue":"httpd install అయి ఉంది. ✔ సమస్య ఇది కాదు."}},{"q":"Next suspect: is the service running?","a":"`systemctl status httpd`","w":["`dnf install httpd` again","`getenforce`"],"clue":"inactive (dead)! Found one. Fix: `sudo systemctl enable --now httpd` starts it now and at every boot.","te":{"q":"తర్వాతి అనుమానం: service run అవుతోందా?","clue":"inactive (dead)! ఒకటి దొరికింది. Fix: `sudo systemctl enable --now httpd` ఇప్పుడే start చేసి, ప్రతి boot లో కూడా start అయ్యేలా చేస్తుంది."}},{"q":"httpd runs now, but her laptop still cannot reach the server. What do you check?","a":"`sudo firewall-cmd --list-all`","w":["`dnf update`","`ls /var/www/html`"],"clue":"http is not in the allowed services! Fix: `sudo firewall-cmd --permanent --add-service=http`, then `sudo firewall-cmd --reload`.","te":{"q":"httpd ఇప్పుడు run అవుతోంది, కానీ laptop నుంచి server చేరట్లేదు. ఏమి check చేస్తారు?","clue":"Allowed services లో http లేదు! Fix: `sudo firewall-cmd --permanent --add-service=http`, తర్వాత `sudo firewall-cmd --reload`."}},{"q":"The site opens, but her new page, moved with `mv` from her home folder, shows 403 Forbidden. Last suspect?","a":"Check the SELinux label with `ls -Z /var/www/html`","w":["Turn SELinux off for good","Reinstall httpd"],"clue":"`mv` keeps the old SELinux label from her home folder, so Apache may not read the file. Fix: `sudo restorecon -Rv /var/www/html`. Case closed! 🎉","te":{"q":"Site తెరుచుకుంది, కానీ home folder నుంచి `mv` తో తెచ్చిన కొత్త page 403 Forbidden చూపిస్తోంది. చివరి అనుమానం?","a":"`ls -Z /var/www/html` తో SELinux label check చేయండి","w":["SELinux ని శాశ్వతంగా off చేయండి","httpd ని మళ్ళీ install చేయండి"],"clue":"`mv` వల్ల file కి home folder నాటి SELinux label అలాగే ఉండిపోయింది, Apache చదవలేదు. Fix: `sudo restorecon -Rv /var/www/html`. Case closed! 🎉"}}]},{"skill":"lx","title":"Ravi’s nginx web server on Ubuntu","te_title":"Ubuntu మీద రవి nginx web server","steps":[{"q":"First suspect: is nginx installed?","a":"`apt list --installed nginx`","w":["`sudo reboot`","`ls /home`"],"clue":"nginx is installed. ✔ Not the problem.","te":{"q":"మొదటి అనుమానం: nginx install అయి ఉందా?","clue":"nginx install అయి ఉంది. ✔ సమస్య ఇది కాదు."}},{"q":"Next suspect: is the nginx service running?","a":"`systemctl status nginx`","w":["`sudo apt install nginx` again","`whoami`"],"clue":"inactive (dead)! Fix: `sudo systemctl enable --now nginx`.","te":{"q":"తర్వాతి అనుమానం: nginx service run అవుతోందా?","clue":"inactive (dead)! Fix: `sudo systemctl enable --now nginx`."}},{"q":"nginx runs, but other computers still cannot reach it. The server uses the ufw firewall. What do you check?","a":"`sudo ufw status`","w":["`sudo apt update`","`cat /etc/hostname`"],"clue":"ufw is active and HTTP is not allowed! Fix: `sudo ufw allow 'Nginx HTTP'`. Case closed! 🎉","te":{"q":"nginx run అవుతోంది, కానీ వేరే computers చేరలేకపోతున్నాయి. Server ufw firewall వాడుతోంది. ఏమి check చేస్తారు?","clue":"ufw active గా ఉంది, HTTP allow కాలేదు! Fix: `sudo ufw allow 'Nginx HTTP'`. Case closed! 🎉"}}]},{"skill":"dk","title":"Asha’s nginx container","te_title":"ఆశా nginx container","steps":[{"q":"She ran `docker run -d --name web nginx`. The browser at localhost:8080 shows nothing. First check?","a":"`docker ps`","w":["`docker images`","`docker system prune`"],"clue":"The container is running, but PORTS shows only 80/tcp, not 8080->80. Found it!","te":{"q":"ఆమె `docker run -d --name web nginx` run చేసింది. Browser లో localhost:8080 ఏమీ చూపించట్లేదు. మొదట ఏమి check చేస్తారు?","clue":"Container run అవుతోంది, కానీ PORTS లో 80/tcp మాత్రమే ఉంది, 8080->80 లేదు. దొరికింది!"}},{"q":"How do you fix it?","a":"Remove it and run again with `docker run -d -p 8080:80 nginx`","w":["`docker restart web`","`docker pull nginx`"],"clue":"`-p 8080:80` publishes container port 80 on host port 8080. Case closed! 🎉","te":{"q":"ఇది ఎలా fix చేస్తారు?","a":"దాన్ని remove చేసి `docker run -d -p 8080:80 nginx` తో మళ్ళీ run చేయండి","w":["`docker restart web`","`docker pull nginx`"],"clue":"`-p 8080:80` container port 80 ని host port 8080 మీద publish చేస్తుంది. Case closed! 🎉"}}]}]},
  {"id":"scanless","type":"tapset","name":"Scan Less, Pay Less","icon":"📊","skills":["gcp","sql","de"],"intro":"In BigQuery (on-demand pricing) the cost depends on how much data your query reads from the columns it uses. Tap ONLY the columns the question needs, then press Check.","ask":"Tap only the columns this query needs","secs":35,"legend":"Green border = a column the query needs. BigQuery reads only the columns you use, so fewer columns = less data scanned = a lower cost. Note: LIMIT does not reduce the data read.","te":{"name":"Scan Less, Pay Less","intro":"BigQuery (on-demand pricing) లో cost, మీ query వాడే columns నుంచి ఎంత data చదివిందో దానిపై ఆధారపడుతుంది. ప్రశ్నకి అవసరమైన columns ని మాత్రమే tap చేసి, Check నొక్కండి.","ask":"ఈ query కి అవసరమైన columns ని మాత్రమే tap చేయండి","legend":"ఆకుపచ్చ అంచు = query కి అవసరమైన column. BigQuery మీరు వాడిన columns మాత్రమే చదువుతుంది, కాబట్టి తక్కువ columns = తక్కువ data scan = తక్కువ cost. గమనిక: LIMIT పెట్టినా చదివే data తగ్గదు."},"scenes":[{"title":"Table: shop.orders","te_title":"Table: shop.orders","q":"Total sales amount per city in 2025.","te_q":"2025 లో ప్రతి city మొత్తం sales amount.","tiles":[{"t":"city","on":true,"why":"You group by city.","te":{"t":"city","why":"City వారీగా group చేస్తారు."}},{"t":"amount","on":true,"why":"You add up the sales amount.","te":{"t":"amount","why":"Sales amount ని కలుపుతారు."}},{"t":"order_date","on":true,"why":"You need it to keep only 2025.","te":{"t":"order_date","why":"2025 మాత్రమే ఉంచడానికి ఇది కావాలి."}},{"t":"order_id","on":false,"why":"Not needed to add up amounts per city.","te":{"t":"order_id","why":"City వారీగా amounts కలపడానికి ఇది అవసరం లేదు."}},{"t":"customer_name","on":false,"why":"The question does not ask about customers.","te":{"t":"customer_name","why":"ప్రశ్న customers గురించి అడగట్లేదు."}},{"t":"item","on":false,"why":"The question is per city, not per item.","te":{"t":"item","why":"ప్రశ్న city వారీగా, item వారీగా కాదు."}},{"t":"delivery_photo","on":false,"why":"Large data you do not use: reading it would add the most cost.","te":{"t":"delivery_photo","why":"పెద్ద data, వాడట్లేదు: దీన్ని చదివితే ఎక్కువ cost పెరుగుతుంది."}},{"t":"notes","on":false,"why":"Free text you do not use here.","te":{"t":"notes","why":"ఇక్కడ వాడని free text."}}]},{"title":"Table: shop.orders","te_title":"Table: shop.orders","q":"Top 5 items by quantity sold.","te_q":"ఎక్కువగా అమ్ముడైన quantity ప్రకారం top 5 items.","tiles":[{"t":"item","on":true,"why":"You group by item.","te":{"t":"item","why":"Item వారీగా group చేస్తారు."}},{"t":"qty","on":true,"why":"You add up the quantity.","te":{"t":"qty","why":"Quantity ని కలుపుతారు."}},{"t":"city","on":false,"why":"The question is about items, not cities.","te":{"t":"city","why":"ప్రశ్న items గురించి, cities గురించి కాదు."}},{"t":"amount","on":false,"why":"It asks for quantity, not money.","te":{"t":"amount","why":"Quantity అడుగుతోంది, డబ్బు కాదు."}},{"t":"order_date","on":false,"why":"No date filter in the question.","te":{"t":"order_date","why":"ప్రశ్నలో date filter లేదు."}},{"t":"customer_name","on":false,"why":"Not needed for item totals.","te":{"t":"customer_name","why":"Item totals కి అవసరం లేదు."}},{"t":"delivery_photo","on":false,"why":"Big and not needed.","te":{"t":"delivery_photo","why":"పెద్దది, అవసరం లేదు."}},{"t":"notes","on":false,"why":"Free text you do not use here.","te":{"t":"notes","why":"ఇక్కడ వాడని free text."}}]},{"title":"Table: college.students","te_title":"Table: college.students","q":"Names and phone numbers of students from Guntur.","te_q":"Guntur నుంచి వచ్చిన students పేర్లు, phone numbers.","tiles":[{"t":"name","on":true,"why":"The question asks for names.","te":{"t":"name","why":"ప్రశ్న పేర్లు అడుగుతోంది."}},{"t":"phone","on":true,"why":"The question asks for phone numbers.","te":{"t":"phone","why":"ప్రశ్న phone numbers అడుగుతోంది."}},{"t":"home_town","on":true,"why":"You filter WHERE home_town = 'Guntur'.","te":{"t":"home_town","why":"WHERE home_town = 'Guntur' తో filter చేస్తారు."}},{"t":"student_id","on":false,"why":"Not asked for, so do not read it.","te":{"t":"student_id","why":"అడగలేదు, కాబట్టి చదవకండి."}},{"t":"branch","on":false,"why":"No branch in the question.","te":{"t":"branch","why":"ప్రశ్నలో branch లేదు."}},{"t":"marks","on":false,"why":"Marks are not asked for.","te":{"t":"marks","why":"Marks అడగలేదు."}},{"t":"photo","on":false,"why":"Big and not needed.","te":{"t":"photo","why":"పెద్దది, అవసరం లేదు."}},{"t":"address","on":false,"why":"Only the home town is used for the filter.","te":{"t":"address","why":"Filter కి home_town మాత్రమే వాడతారు."}}]}]},
  {"id": "watchtrail", "type": "swipe", "name": "Watch or Trail?", "icon": "🔭", "skills": ["aws"], "intro": "Swipe each situation: is it CloudWatch (how things perform) or CloudTrail (who did what)?", "left": "CloudWatch", "right": "CloudTrail", "secs": 8, "rounds": 6, "te": {"name": "Watch లేదా Trail?", "intro": "ప్రతి situation ని swipe చేయండి: ఇది CloudWatch (ఎలా పనిచేస్తోంది) లేదా CloudTrail (ఎవరు ఏమి చేశారు)?", "left": "CloudWatch", "right": "CloudTrail"}, "items": [{"t": "CPU of a server stays above 80% for 5 minutes", "a": "l", "why": "CPU is a metric, and a CloudWatch alarm can watch it.", "te": {"t": "Server CPU 5 నిమిషాలు 80% పైన ఉండటం", "why": "CPU ఒక metric, CloudWatch alarm దాన్ని గమనించగలదు."}}, {"t": "Which user deleted the bucket asha-reports?", "a": "r", "why": "Deleting a bucket is an API call, and CloudTrail records who made it.", "te": {"t": "asha-reports bucket ని ఏ user delete చేశారు?", "why": "Bucket delete చేయడం ఒక API call, ఎవరు చేశారో CloudTrail record చేస్తుంది."}}, {"t": "Graph of Lambda errors on a dashboard", "a": "l", "why": "Dashboards show CloudWatch metrics such as Lambda errors.", "te": {"t": "Dashboard లో Lambda errors graph", "why": "Dashboards లో Lambda errors లాంటి CloudWatch metrics కనిపిస్తాయి."}}, {"t": "Who signed in to the AWS console at 2 AM?", "a": "r", "why": "Console sign-ins are recorded as events in CloudTrail.", "te": {"t": "రాత్రి 2 కి AWS console లో ఎవరు sign in అయ్యారు?", "why": "Console sign-ins CloudTrail లో events గా record అవుతాయి."}}, {"t": "Error lines printed by a Lambda function", "a": "l", "why": "Lambda sends its logs to CloudWatch Logs.", "te": {"t": "Lambda function print చేసిన error lines", "why": "Lambda తన logs ని CloudWatch Logs కి పంపుతుంది."}}, {"t": "Who changed a security group rule yesterday?", "a": "r", "why": "Changing a rule is an API call, so CloudTrail shows who did it.", "te": {"t": "నిన్న security group rule ని ఎవరు మార్చారు?", "why": "Rule మార్చడం ఒక API call, కాబట్టి ఎవరు చేశారో CloudTrail చూపిస్తుంది."}}, {"t": "Alarm that emails you when a website is slow", "a": "l", "why": "Alarms on performance metrics belong to CloudWatch.", "te": {"t": "Website నెమ్మదిస్తే మీకు email పంపే alarm", "why": "Performance metrics మీద alarms CloudWatch కి చెందుతాయి."}}, {"t": "Which IAM user called StopInstances?", "a": "r", "why": "CloudTrail records the API call name and the caller.", "te": {"t": "StopInstances ని ఏ IAM user call చేశారు?", "why": "API call పేరు, call చేసిన వారిని CloudTrail record చేస్తుంది."}}, {"t": "Requests per minute to your API", "a": "l", "why": "Request count is a metric you can chart in CloudWatch.", "te": {"t": "మీ API కి నిమిషానికి వచ్చే requests", "why": "Request count ఒక metric, దాన్ని CloudWatch లో chart చేయొచ్చు."}}, {"t": "Who created a new IAM user in the account?", "a": "r", "why": "Creating a user is an API call, so it appears in CloudTrail.", "te": {"t": "Account లో కొత్త IAM user ని ఎవరు create చేశారు?", "why": "User create చేయడం ఒక API call, కాబట్టి CloudTrail లో కనిపిస్తుంది."}}, {"t": "How long a Lambda function takes to run", "a": "l", "why": "Duration is a metric that CloudWatch collects for Lambda.", "te": {"t": "Lambda function run అవ్వడానికి ఎంత సమయం పడుతుంది", "why": "Duration అనేది Lambda కోసం CloudWatch సేకరించే metric."}}, {"t": "Who changed the policy of an S3 bucket?", "a": "r", "why": "Changing a bucket policy is an API call, so CloudTrail records it.", "te": {"t": "S3 bucket policy ని ఎవరు మార్చారు?", "why": "Bucket policy మార్చడం ఒక API call, CloudTrail దాన్ని record చేస్తుంది."}}, {"t": "Database connections shown on a graph", "a": "l", "why": "Connections are a performance metric shown in CloudWatch.", "te": {"t": "Graph లో కనిపించే database connections", "why": "Connections ఒక performance metric, CloudWatch లో కనిపిస్తుంది."}}, {"t": "Who launched 10 new servers last night?", "a": "r", "why": "Launching servers is an API call, and CloudTrail shows the user.", "te": {"t": "నిన్న రాత్రి 10 కొత్త servers ని ఎవరు launch చేశారు?", "why": "Servers launch చేయడం ఒక API call, ఏ user చేశారో CloudTrail చూపిస్తుంది."}}, {"t": "Log line “payment failed” from your app", "a": "l", "why": "Application logs are collected in CloudWatch Logs.", "te": {"t": "మీ app నుంచి “payment failed” log line", "why": "Application logs CloudWatch Logs లో చేరతాయి."}}, {"t": "Which access key made a DeleteBucket call?", "a": "r", "why": "CloudTrail records the access key used for each API call.", "te": {"t": "DeleteBucket call చేసిన access key ఏది?", "why": "ప్రతి API call కి వాడిన access key ని CloudTrail record చేస్తుంది."}}, {"t": "Memory and disk graph of a busy server", "a": "l", "why": "Memory and disk-space metrics need the CloudWatch agent on the server, but the graphs are still CloudWatch.", "te": {"t": "Busy server memory, disk graph", "why": "Memory, disk-space metrics కోసం server మీద CloudWatch agent కావాలి, కానీ ఆ graphs CloudWatch లోనే ఉంటాయి."}}, {"t": "A history of API calls made in your account", "a": "r", "why": "CloudTrail is the record of API calls: who did what, and when.", "te": {"t": "మీ account లో జరిగిన API calls చరిత్ర", "why": "CloudTrail అంటే API calls record: ఎవరు, ఏమి, ఎప్పుడు చేశారు."}}]},
  {"id": "filterformat", "type": "swipe", "name": "Filter or Format?", "icon": "🔎", "skills": ["gcp"], "intro": "Swipe each task: does it need --filter (which rows are listed) or --format (how the output looks)?", "left": "--filter", "right": "--format", "secs": 8, "rounds": 6, "te": {"name": "Filter లేదా Format?", "intro": "ప్రతి పనిని swipe చేయండి: దీనికి --filter (ఏ rows list అవ్వాలి) కావాలా, లేదా --format (output ఎలా కనిపించాలి) కావాలా?", "left": "--filter", "right": "--format"}, "items": [{"t": "Show only VMs in the zone asia-south1-a", "a": "l", "why": "`--filter=\"zone:asia-south1-a\"` picks which VMs are listed.", "te": {"t": "asia-south1-a zone లోని VMs మాత్రమే చూపించు", "why": "`--filter=\"zone:asia-south1-a\"` ఏ VMs list అవ్వాలో ఎంచుకుంటుంది."}}, {"t": "Print only the names, one per line", "a": "r", "why": "`--format=\"value(name)\"` changes how the output looks, not which rows.", "te": {"t": "పేర్లు మాత్రమే, ఒక్కో line లో ఒకటి", "why": "`--format=\"value(name)\"` output ఎలా కనిపించాలో మారుస్తుంది, ఏ rows అనేది కాదు."}}, {"t": "Keep only VMs with status RUNNING", "a": "l", "why": "`--filter=\"status=RUNNING\"` drops the rows that do not match.", "te": {"t": "status RUNNING ఉన్న VMs మాత్రమే ఉంచు", "why": "`--filter=\"status=RUNNING\"` సరిపోని rows ని తీసేస్తుంది."}}, {"t": "Show the result as JSON", "a": "r", "why": "`--format=json` only changes the shape of the output.", "te": {"t": "ఫలితాన్ని JSON గా చూపించు", "why": "`--format=json` output రూపాన్ని మాత్రమే మారుస్తుంది."}}, {"t": "List only VMs whose name starts with web", "a": "l", "why": "`--filter=\"name~^web\"` matches names, so only those rows stay.", "te": {"t": "పేరు web తో మొదలయ్యే VMs మాత్రమే list చేయి", "why": "`--filter=\"name~^web\"` పేర్లను match చేస్తుంది, ఆ rows మాత్రమే మిగులుతాయి."}}, {"t": "Show name, zone and status as a table", "a": "r", "why": "`--format=\"table(name,zone,status)\"` picks the columns and the table look.", "te": {"t": "name, zone, status ని table గా చూపించు", "why": "`--format=\"table(name,zone,status)\"` columns ని, table రూపాన్ని ఎంచుకుంటుంది."}}, {"t": "Show only resources with the label env=dev", "a": "l", "why": "`--filter=\"labels.env=dev\"` decides which resources are listed.", "te": {"t": "label env=dev ఉన్న resources మాత్రమే చూపించు", "why": "`--filter=\"labels.env=dev\"` ఏ resources list అవ్వాలో నిర్ణయిస్తుంది."}}, {"t": "Print the result as CSV with name and status", "a": "r", "why": "`--format=\"csv(name,status)\"` writes the output as CSV.", "te": {"t": "name, status తో ఫలితాన్ని CSV గా print చేయి", "why": "`--format=\"csv(name,status)\"` output ని CSV గా రాస్తుంది."}}, {"t": "List only VMs with the machine type e2-micro", "a": "l", "why": "`--filter=\"machineType~e2-micro\"` keeps only the matching VMs.", "te": {"t": "Machine type e2-micro ఉన్న VMs మాత్రమే list చేయి", "why": "`--filter=\"machineType~e2-micro\"` match అయ్యే VMs ని మాత్రమే ఉంచుతుంది."}}, {"t": "Show the result as YAML", "a": "r", "why": "`--format=yaml` changes how the output is written.", "te": {"t": "ఫలితాన్ని YAML గా చూపించు", "why": "`--format=yaml` output ఎలా రాయాలో మారుస్తుంది."}}, {"t": "List only disks in the zone asia-south1-b", "a": "l", "why": "`--filter=\"zone:asia-south1-b\"` keeps only the disks in that zone.", "te": {"t": "asia-south1-b zone లోని disks మాత్రమే list చేయి", "why": "`--filter=\"zone:asia-south1-b\"` ఆ zone లోని disks ని మాత్రమే ఉంచుతుంది."}}, {"t": "Print only the internal IP of each VM", "a": "r", "why": "`--format=\"value(networkInterfaces[0].networkIP)\"` prints just that one field.", "te": {"t": "ప్రతి VM యొక్క internal IP మాత్రమే print చేయి", "why": "`--format=\"value(networkInterfaces[0].networkIP)\"` ఆ ఒక్క field ని మాత్రమే print చేస్తుంది."}}, {"t": "Keep only VMs that are not RUNNING", "a": "l", "why": "`--filter=\"status!=RUNNING\"` keeps only the rows that are not running.", "te": {"t": "RUNNING కాని VMs మాత్రమే ఉంచు", "why": "`--filter=\"status!=RUNNING\"` run అవ్వని rows ని మాత్రమే ఉంచుతుంది."}}, {"t": "Show the table without the heading row", "a": "r", "why": "`--format=\"table[no-heading](name)\"` changes how the table looks.", "te": {"t": "Heading row లేకుండా table చూపించు", "why": "`--format=\"table[no-heading](name)\"` table రూపాన్ని మారుస్తుంది."}}, {"t": "Show only the VMs where the name contains asha", "a": "l", "why": "`--filter=\"name~asha\"` (a regex match) decides which VMs stay in the list.", "te": {"t": "పేరులో asha ఉన్న VMs మాత్రమే చూపించు", "why": "`--filter=\"name~asha\"` (regex match) ఏ VMs list లో ఉండాలో నిర్ణయిస్తుంది."}}, {"t": "Show only the name and status fields as JSON", "a": "r", "why": "`--format=\"json(name,status)\"` picks fields and the JSON look.", "te": {"t": "name, status fields ని మాత్రమే JSON గా చూపించు", "why": "`--format=\"json(name,status)\"` fields ని, JSON రూపాన్ని ఎంచుకుంటుంది."}}]},
  {"id": "locksmith", "type": "tapset", "name": "Least Privilege Locksmith", "icon": "🔑", "skills": ["aws"], "intro": "Each job needs only a few permissions. Tap ONLY what the policy needs, then press Check.", "ask": "Tap only what the policy needs", "secs": 45, "legend": "Green border = the policy needs it. Give each job the least permission that works.", "te": {"name": "Least Privilege Locksmith", "intro": "ప్రతి job కి కొన్ని permissions మాత్రమే కావాలి. Policy కి అవసరమైనవి మాత్రమే tap చేసి, Check నొక్కండి.", "ask": "Policy కి అవసరమైనవి మాత్రమే tap చేయండి", "legend": "ఆకుపచ్చ అంచు = policy కి అవసరం. ప్రతి job కి పని చేసే అతి తక్కువ permission ఇవ్వండి."}, "scenes": [{"title": "Job: a Lambda function reads files from the bucket asha-reports", "te_title": "Job: ఒక Lambda function, bucket asha-reports లోని files ని చదువుతుంది", "tiles": [{"t": "`s3:GetObject`", "on": true, "why": "Reading a file from S3 needs GetObject.", "te": {"t": "`s3:GetObject`", "why": "S3 నుంచి file చదవడానికి GetObject కావాలి."}}, {"t": "`arn:aws:s3:::asha-reports/*`", "on": true, "why": "This names only the files inside asha-reports.", "te": {"t": "`arn:aws:s3:::asha-reports/*`", "why": "ఇది asha-reports లోని files ని మాత్రమే సూచిస్తుంది."}}, {"t": "`\"Effect\": \"Allow\"`", "on": true, "why": "The policy statement must allow the action.", "te": {"t": "`\"Effect\": \"Allow\"`", "why": "Policy statement action ని allow చేయాలి."}}, {"t": "`s3:DeleteObject`", "on": false, "why": "The job only reads, so it must not delete.", "te": {"t": "`s3:DeleteObject`", "why": "Job చదవడమే చేస్తుంది, delete చేయకూడదు."}}, {"t": "`s3:*`", "on": false, "why": "This allows every S3 action, far more than reading.", "te": {"t": "`s3:*`", "why": "ఇది ప్రతి S3 action ని allow చేస్తుంది, చదవడం కంటే చాలా ఎక్కువ."}}, {"t": "`\"Resource\": \"*\"`", "on": false, "why": "This covers every resource, not only asha-reports.", "te": {"t": "`\"Resource\": \"*\"`", "why": "ఇది asha-reports మాత్రమే కాదు, ప్రతి resource ని కవర్ చేస్తుంది."}}, {"t": "`s3:PutObject`", "on": false, "why": "Writing files is not part of this job.", "te": {"t": "`s3:PutObject`", "why": "Files రాయడం ఈ job లో లేదు."}}, {"t": "`iam:PassRole`", "on": false, "why": "This job passes no role to any service.", "te": {"t": "`iam:PassRole`", "why": "ఈ job ఏ service కీ role ని pass చేయదు."}}]}, {"title": "Job: an app reads one student record by ID from the DynamoDB table students", "te_title": "Job: ఒక app, DynamoDB table students నుంచి ID ప్రకారం ఒక student record ని చదువుతుంది", "tiles": [{"t": "`dynamodb:GetItem`", "on": true, "why": "GetItem reads one item by its key.", "te": {"t": "`dynamodb:GetItem`", "why": "GetItem ఒక item ని దాని key తో చదువుతుంది."}}, {"t": "`arn:aws:dynamodb:ap-south-1:111122223333:table/students`", "on": true, "why": "This points to only the students table.", "te": {"t": "`arn:aws:dynamodb:ap-south-1:111122223333:table/students`", "why": "ఇది students table ని మాత్రమే సూచిస్తుంది."}}, {"t": "`\"Effect\": \"Allow\"`", "on": true, "why": "The statement must allow the action.", "te": {"t": "`\"Effect\": \"Allow\"`", "why": "Statement action ని allow చేయాలి."}}, {"t": "`dynamodb:PutItem`", "on": false, "why": "The app only reads, so it must not write.", "te": {"t": "`dynamodb:PutItem`", "why": "App చదవడమే చేస్తుంది, రాయకూడదు."}}, {"t": "`dynamodb:DeleteItem`", "on": false, "why": "Deleting records is not part of the job.", "te": {"t": "`dynamodb:DeleteItem`", "why": "Records delete చేయడం ఈ job లో లేదు."}}, {"t": "`dynamodb:DeleteTable`", "on": false, "why": "This could remove the whole table.", "te": {"t": "`dynamodb:DeleteTable`", "why": "ఇది మొత్తం table ని తీసేయగలదు."}}, {"t": "`dynamodb:*`", "on": false, "why": "This allows every DynamoDB action.", "te": {"t": "`dynamodb:*`", "why": "ఇది ప్రతి DynamoDB action ని allow చేస్తుంది."}}, {"t": "`\"Resource\": \"*\"`", "on": false, "why": "This covers every table in the account.", "te": {"t": "`\"Resource\": \"*\"`", "why": "ఇది account లోని ప్రతి table ని కవర్ చేస్తుంది."}}]}, {"title": "Job: a script sends alerts to the SNS topic alerts", "te_title": "Job: ఒక script, SNS topic alerts కి alerts పంపుతుంది", "tiles": [{"t": "`sns:Publish`", "on": true, "why": "Publish sends a message to a topic.", "te": {"t": "`sns:Publish`", "why": "Publish ఒక topic కి message పంపుతుంది."}}, {"t": "`arn:aws:sns:ap-south-1:111122223333:alerts`", "on": true, "why": "This points to only the alerts topic.", "te": {"t": "`arn:aws:sns:ap-south-1:111122223333:alerts`", "why": "ఇది alerts topic ని మాత్రమే సూచిస్తుంది."}}, {"t": "`\"Effect\": \"Allow\"`", "on": true, "why": "The statement must allow the action.", "te": {"t": "`\"Effect\": \"Allow\"`", "why": "Statement action ని allow చేయాలి."}}, {"t": "`sns:Subscribe`", "on": false, "why": "The script only sends, so it should not add subscribers.", "te": {"t": "`sns:Subscribe`", "why": "Script పంపడమే చేస్తుంది, subscribers ని చేర్చకూడదు."}}, {"t": "`sns:DeleteTopic`", "on": false, "why": "Deleting the topic is not part of the job.", "te": {"t": "`sns:DeleteTopic`", "why": "Topic ని delete చేయడం ఈ job లో లేదు."}}, {"t": "`sns:*`", "on": false, "why": "This allows every SNS action.", "te": {"t": "`sns:*`", "why": "ఇది ప్రతి SNS action ని allow చేస్తుంది."}}, {"t": "`\"Resource\": \"*\"`", "on": false, "why": "This covers every topic, not only alerts.", "te": {"t": "`\"Resource\": \"*\"`", "why": "ఇది alerts మాత్రమే కాదు, ప్రతి topic ని కవర్ చేస్తుంది."}}, {"t": "`iam:PassRole`", "on": false, "why": "PassRole hands a role to a service; this job passes none.", "te": {"t": "`iam:PassRole`", "why": "PassRole ఒక service కి role ని ఇస్తుంది; ఈ job ఏదీ pass చేయదు."}}]}]},
  {"id": "leakhunter", "type": "tapset", "name": "Leak Hunter", "icon": "🕵️", "skills": ["gcp", "aws"], "intro": "Look at each project. Tap every security risk, then press Check. Safe items stay untapped.", "ask": "Tap every security risk", "secs": 45, "legend": "Green border = a security risk. Read the line under each tile.", "te": {"name": "Leak Hunter", "intro": "ప్రతి project ని చూడండి. ప్రతి security risk ని tap చేసి, Check నొక్కండి. Safe వాటిని tap చేయకండి.", "ask": "ప్రతి security risk ని tap చేయండి", "legend": "ఆకుపచ్చ అంచు = security risk. ప్రతి tile కింద ఉన్న line చదవండి."}, "scenes": [{"skill": "gcp", "title": "Asha’s Google Cloud project", "te_title": "ఆశా Google Cloud project", "tiles": [{"t": "Service account key file committed to Git", "on": true, "why": "Anyone who reads the repo can use the key.", "te": {"t": "Git లో commit చేసిన service account key file", "why": "Repo చదివే ఎవరైనా ఆ key ని వాడగలరు."}}, {"t": "Cloud Run service with `--allow-unauthenticated` that should be private", "on": true, "why": "Anyone on the internet can call it.", "te": {"t": "Private గా ఉండాల్సిన, `--allow-unauthenticated` ఉన్న Cloud Run service", "why": "Internet లో ఎవరైనా దాన్ని call చేయగలరు."}}, {"t": "Bucket of customer files shared with `allUsers`", "on": true, "why": "`allUsers` means anyone on the internet can read the customer files.", "te": {"t": "Customer files ఉన్న bucket ని `allUsers` తో share చేశారు", "why": "`allUsers` అంటే internet లో ఎవరైనా ఆ customer files ని చదవగలరు."}}, {"t": "Firewall rule allowing SSH from `0.0.0.0/0`", "on": true, "why": "It opens SSH to the whole internet.", "te": {"t": "`0.0.0.0/0` నుంచి SSH allow చేసే firewall rule", "why": "ఇది SSH ని మొత్తం internet కి తెరుస్తుంది."}}, {"t": "Passwords kept in Secret Manager", "on": false, "why": "Secret Manager stores secrets safely, away from the code.", "te": {"t": "Secret Manager లో ఉంచిన passwords", "why": "Secret Manager secrets ని code కి దూరంగా సురక్షితంగా ఉంచుతుంది."}}, {"t": "GitHub deploys with Workload Identity Federation", "on": false, "why": "It needs no long-lived key file.", "te": {"t": "Workload Identity Federation తో GitHub deploy", "why": "దీనికి ఎక్కువ కాలం ఉండే key file అవసరం లేదు."}}, {"t": "Cloud Run service that needs sign-in to call", "on": false, "why": "It is private, as intended.", "te": {"t": "Call చేయడానికి sign-in అవసరమైన Cloud Run service", "why": "ఇది అనుకున్నట్టే private."}}, {"t": "Bucket open only to the team’s Google group", "on": false, "why": "Only named people get access.", "te": {"t": "Team Google group కి మాత్రమే తెరిచిన bucket", "why": "పేరున్న వారికే access ఉంటుంది."}}]}, {"skill": "aws", "title": "Ravi’s AWS account", "te_title": "రవి AWS account", "tiles": [{"t": "AWS access key written in code pushed to GitHub", "on": true, "why": "Bots scan public repos for keys and use them.", "te": {"t": "GitHub కి push చేసిన code లో రాసిన AWS access key", "why": "Bots public repos లో keys కోసం వెతికి వాటిని వాడతాయి."}}, {"t": "S3 Block Public Access turned off on a private bucket", "on": true, "why": "One wrong setting can then make files public.", "te": {"t": "Private bucket మీద S3 Block Public Access off", "why": "అప్పుడు ఒక తప్పు setting తో files public అవ్వచ్చు."}}, {"t": "Security group allowing SSH from `0.0.0.0/0`", "on": true, "why": "It opens SSH to the whole internet.", "te": {"t": "`0.0.0.0/0` నుంచి SSH allow చేసే security group", "why": "ఇది SSH ని మొత్తం internet కి తెరుస్తుంది."}}, {"t": "Root user used daily, with no MFA", "on": true, "why": "Root has full power, so it needs MFA and rare use.", "te": {"t": "MFA లేకుండా రోజూ వాడే root user", "why": "Root కి పూర్తి అధికారం ఉంది, కాబట్టి MFA కావాలి, అరుదుగా వాడాలి."}}, {"t": "MFA turned on for admin users", "on": false, "why": "A second step protects the sign-in.", "te": {"t": "Admin users కి MFA on", "why": "రెండో step sign-in ని కాపాడుతుంది."}}, {"t": "EC2 instance using an IAM role", "on": false, "why": "A role gives temporary credentials, so no key in code.", "te": {"t": "IAM role వాడే EC2 instance", "why": "Role తాత్కాలిక credentials ఇస్తుంది, code లో key ఉండదు."}}, {"t": "Database password kept in AWS Secrets Manager", "on": false, "why": "The secret stays out of the code.", "te": {"t": "AWS Secrets Manager లో ఉంచిన database password", "why": "Secret code లో ఉండదు."}}, {"t": "CloudTrail turned on", "on": false, "why": "It records who did what in the account.", "te": {"t": "CloudTrail on", "why": "Account లో ఎవరు ఏమి చేశారో ఇది record చేస్తుంది."}}]}, {"skill": "gcp", "title": "Terraform and CI for a Google Cloud project", "te_title": "Google Cloud project కోసం Terraform, CI", "tiles": [{"t": "`terraform.tfstate` committed to Git", "on": true, "why": "The state file can contain secret values.", "te": {"t": "Git లో commit చేసిన `terraform.tfstate`", "why": "State file లో secret values ఉండవచ్చు."}}, {"t": "Service account key file saved inside the repo", "on": true, "why": "Anyone with the repo can use the key.", "te": {"t": "Repo లోపల save చేసిన service account key file", "why": "Repo ఉన్న ఎవరైనా ఆ key ని వాడగలరు."}}, {"t": "Database password typed directly in a `.tf` file", "on": true, "why": "The password sits in Git history for everyone.", "te": {"t": "`.tf` file లో నేరుగా రాసిన database password", "why": "Password అందరికీ కనిపించేలా Git history లో ఉంటుంది."}}, {"t": "Owner role given to the CI service account", "on": true, "why": "A deploy job needs only a small role, not full control.", "te": {"t": "CI service account కి ఇచ్చిన Owner role", "why": "Deploy job కి చిన్న role చాలు, పూర్తి control అవసరం లేదు."}}, {"t": "Terraform state kept in a private Cloud Storage bucket", "on": false, "why": "Remote state with limited access is safer.", "te": {"t": "Private Cloud Storage bucket లో ఉంచిన Terraform state", "why": "పరిమిత access ఉన్న remote state సురక్షితం."}}, {"t": "CI signs in with Workload Identity Federation", "on": false, "why": "No long-lived key file is needed.", "te": {"t": "Workload Identity Federation తో CI sign in", "why": "ఎక్కువ కాలం ఉండే key file అవసరం లేదు."}}, {"t": "`.gitignore` lists `*.tfstate`", "on": false, "why": "It keeps state files out of Git.", "te": {"t": "`.gitignore` లో `*.tfstate`", "why": "ఇది state files ని Git లోకి రాకుండా ఆపుతుంది."}}, {"t": "Password read from Secret Manager at deploy time", "on": false, "why": "The password never sits in the code.", "te": {"t": "Deploy సమయంలో Secret Manager నుంచి చదివే password", "why": "Password code లో ఉండదు."}}]}]},
  {"id": "pager", "outro": "On-call habit: read the logs first, then fix one problem at a time.", "type": "chain", "name": "2 AM Pager", "icon": "📟", "skills": ["aws", "gcp"], "intro": "It is 2 AM and something is broken. Be the on-call engineer: at each step pick the right check and fix every problem.", "te": {"name": "రాత్రి 2 గంటల Pager", "outro": "On-call అలవాటు: ముందు logs చదవండి, తర్వాత ఒక్కో సమస్యని fix చేయండి.", "intro": "రాత్రి 2 గంటలు, ఏదో పనిచేయట్లేదు. On-call engineer లా ప్రతి step లో సరైన check ఎంచుకుని, ప్రతి సమస్యనూ fix చేయండి."}, "cases": [{"skill": "aws", "title": "Ravi’s Lambda function fails at night", "te_title": "రాత్రి fail అయ్యే రవి Lambda function", "steps": [{"q": "Ravi’s Lambda function `process-orders` failed at 2 AM. Where do you look first?", "a": "CloudWatch Logs, log group `/aws/lambda/process-orders`", "w": ["The list of S3 buckets", "The list of EC2 instances"], "clue": "Lambda writes its logs to CloudWatch Logs, in a log group named `/aws/lambda/` plus the function name.", "te": {"q": "రవి Lambda function `process-orders` రాత్రి 2 కి fail అయింది. మొదట ఎక్కడ చూస్తారు?", "a": "CloudWatch Logs, log group `/aws/lambda/process-orders`", "w": ["S3 buckets list", "EC2 instances list"], "clue": "Lambda తన logs ని CloudWatch Logs లో, `/aws/lambda/` తో function పేరు చేర్చిన log group లో రాస్తుంది."}}, {"q": "The newest log stream says AccessDenied when the function reads a file from S3. What does this mean?", "a": "The function’s execution role does not allow that action", "w": ["The S3 bucket is too big", "The function ran out of memory"], "clue": "A Lambda function uses its execution role when it calls other services. AccessDenied means that role’s policy does not allow the call.", "te": {"q": "S3 నుంచి file చదివేటప్పుడు కొత్త log stream లో AccessDenied కనిపిస్తోంది. దీని అర్థం ఏమిటి?", "a": "Function యొక్క execution role ఆ action ని allow చేయదు", "w": ["S3 bucket చాలా పెద్దది", "Function కి memory సరిపోలేదు"], "clue": "Lambda function వేరే services ని call చేసేటప్పుడు తన execution role ని వాడుతుంది. AccessDenied అంటే ఆ role యొక్క policy ఆ call ని allow చేయదు."}}, {"q": "How do you fix it?", "a": "Add only the needed action, such as `s3:GetObject`, to the execution role’s policy", "w": ["Give the role full AdministratorAccess", "Add the permission to your own IAM user"], "clue": "Fix the role the function uses, and give it only what it needs (least privilege).", "te": {"q": "దీన్ని ఎలా fix చేస్తారు?", "a": "Execution role policy లో అవసరమైన action మాత్రమే, ఉదాహరణకు `s3:GetObject`, చేర్చండి", "w": ["Role కి పూర్తి AdministratorAccess ఇవ్వండి", "మీ సొంత IAM user కి permission చేర్చండి"], "clue": "Function వాడే role ని fix చేయండి, దానికి కావలసినవి మాత్రమే ఇవ్వండి (least privilege)."}}, {"q": "Next night the logs say `Task timed out after` some seconds. What is the fix?", "a": "Raise the function’s timeout setting, or make the code faster", "w": ["Make the S3 bucket bigger", "Delete the log group"], "clue": "The function was stopped because it ran longer than its timeout. Raise the timeout, or speed up the code. Case closed! 🎉", "te": {"q": "మరుసటి రాత్రి logs లో `Task timed out after` కొన్ని seconds అని వస్తోంది. Fix ఏమిటి?", "a": "Function timeout setting పెంచండి, లేదా code ని వేగంగా చేయండి", "w": ["S3 bucket ని పెద్దది చేయండి", "Log group ని delete చేయండి"], "clue": "Function తన timeout కంటే ఎక్కువ సేపు run అయినందున ఆగిపోయింది. Timeout పెంచండి, లేదా code ని వేగవంతం చేయండి. Case closed! 🎉"}}]}, {"skill": "gcp", "title": "Why won’t my Cloud Run app start?", "te_title": "నా Cloud Run app ఎందుకు start అవ్వట్లేదు?", "steps": [{"q": "Asha runs `gcloud run deploy` and gets an error: the Cloud Run Admin API is not enabled in the project. What is the fix?", "a": "`gcloud services enable run.googleapis.com`", "w": ["`gcloud run services delete`", "`gcloud auth login` again"], "clue": "The API must be enabled once for the project. Found problem one!", "te": {"q": "ఆశా `gcloud run deploy` run చేస్తే, project లో Cloud Run Admin API enable కాలేదని error వచ్చింది. Fix ఏమిటి?", "a": "`gcloud services enable run.googleapis.com`", "w": ["`gcloud run services delete`", "మళ్ళీ `gcloud auth login`"], "clue": "API ని project కి ఒకసారి enable చేయాలి. మొదటి సమస్య దొరికింది!"}}, {"q": "Now the deploy says the container failed to start and listen on the expected port. Where do you look first?", "a": "The revision’s logs and the app code", "w": ["The billing page", "The bucket list"], "clue": "The logs and code show the app listens on a hard-coded port 3000. Found problem two!", "te": {"q": "ఇప్పుడు container start అయి, expected port మీద listen చేయలేకపోయిందని deploy చెబుతోంది. మొదట ఎక్కడ చూస్తారు?", "a": "Revision logs, app code", "w": ["Billing page", "Bucket list"], "clue": "Logs, code చూస్తే app hard-code చేసిన port 3000 మీద listen చేస్తోందని తెలుస్తుంది. రెండో సమస్య దొరికింది!"}}, {"q": "How do you fix the port?", "a": "Make the app listen on the port from the `PORT` environment variable", "w": ["Open port 3000 in a firewall rule", "Restart the service again and again"], "clue": "Cloud Run tells the container which port to use through the `PORT` environment variable. Read it instead of hard-coding 3000 (or deploy with `--port=3000`).", "te": {"q": "Port ని ఎలా fix చేస్తారు?", "a": "`PORT` environment variable లోని port మీద app listen చేసేలా మార్చండి", "w": ["Firewall rule లో port 3000 తెరవండి", "Service ని మళ్ళీ మళ్ళీ restart చేయండి"], "clue": "Cloud Run ఏ port వాడాలో container కి `PORT` environment variable ద్వారా చెబుతుంది. 3000 hard-code చేయకుండా దాన్ని చదవండి (లేదా `--port=3000` తో deploy చేయండి)."}}, {"q": "The app runs now, but the browser shows 403 Forbidden. Last suspect?", "a": "The service is private: grant `roles/run.invoker`, or make it public on purpose", "w": ["Enable the API again", "Change the port to 80"], "clue": "A private Cloud Run service only accepts callers with `roles/run.invoker`. Grant it to the right people, or allow public access only if you want that. Case closed! 🎉", "te": {"q": "App run అవుతోంది, కానీ browser లో 403 Forbidden వస్తోంది. చివరి అనుమానం?", "a": "Service private: `roles/run.invoker` ఇవ్వండి, లేదా కావాలనే public చేయండి", "w": ["API ని మళ్ళీ enable చేయండి", "Port ని 80 కి మార్చండి"], "clue": "Private Cloud Run service కి `roles/run.invoker` ఉన్నవారి calls మాత్రమే వస్తాయి. సరైన వారికి ఇవ్వండి, లేదా మీకు కావాలంటేనే public access ఇవ్వండి. Case closed! 🎉"}}]}]},
  {"id": "starbuilder", "type": "swipe", "name": "Star Builder", "icon": "⭐", "skills": ["sql", "pbi", "de"], "intro": "You are building a star schema for a shop's sales. Swipe each column or table to where it belongs: Dimension (left: describes who, what, where, when) or Fact (right: numbers and events).", "rules": ["Fact: numbers you add up, and tables where each row is an event (a sale line, a payment)", "Dimension: words that describe a sale (customer, product, store, date) and that you group or filter by"], "left": "Dimension", "right": "Fact", "secs": 9, "rounds": 6, "te": {"name": "Star Builder", "intro": "మీరు ఒక shop sales కోసం star schema తయారు చేస్తున్నారు. ప్రతి column లేదా table ని దాని స్థానానికి swipe చేయండి: Dimension (ఎడమ: ఎవరు, ఏది, ఎక్కడ, ఎప్పుడు అని చెబుతుంది) లేదా Fact (కుడి: numbers, events).", "rules": ["Fact: మీరు add చేసే numbers, ఇంకా ప్రతి row ఒక event గా ఉండే tables (ఒక sale line, ఒక payment)", "Dimension: sale గురించి చెప్పే మాటలు (customer, product, store, date), వీటితో group లేదా filter చేస్తారు"], "left": "Dimension", "right": "Fact"}, "items": [{"t": "`sale_amount`", "a": "r", "why": "Reports SUM it (total sales), so it is a measure in the fact table.", "te": {"t": "`sale_amount`", "why": "Reports లో దీన్ని SUM చేస్తారు (total sales), అందుకే ఇది fact table లో measure."}}, {"t": "`customer_city`", "a": "l", "why": "You group sales by city, but you never add cities up. It describes the customer, so it goes in the customer dimension.", "te": {"t": "`customer_city`", "why": "Sales ని city వారీగా group చేస్తారు, కానీ city ని add చేయలేరు. ఇది customer గురించి చెబుతుంది, అందుకే customer dimension లో ఉంటుంది."}}, {"t": "`quantity` sold", "a": "r", "why": "Units sold are added up (total pieces sold), so quantity is a measure in the fact table.", "te": {"t": "అమ్మిన `quantity`", "why": "అమ్మిన pieces ని add చేస్తారు (మొత్తం ఎన్ని అమ్మారు), అందుకే quantity fact table లో measure."}}, {"t": "`product_category`", "a": "l", "why": "Category describes the product and is used to group reports (sales by category), so it lives in the product dimension.", "te": {"t": "`product_category`", "why": "Category, product గురించి చెబుతుంది; reports ని category వారీగా group చేస్తారు. అందుకే product dimension లో ఉంటుంది."}}, {"t": "Table with one row per sale line", "a": "r", "why": "Each row is an event: one product on one bill. That is the grain of the sales fact table.", "te": {"t": "ప్రతి sale line కి ఒక row ఉన్న table", "why": "ప్రతి row ఒక event: ఒక bill లో ఒక product. ఇదే sales fact table grain."}}, {"t": "The month name of the order date", "a": "l", "why": "Month name describes the date, so it is stored once per day in the date dimension, not in every fact row.", "te": {"t": "Order date లోని month name", "why": "Month name, date గురించి చెబుతుంది. అందుకే ప్రతి fact row లో కాకుండా date dimension లో ఒక్కసారి ఉంటుంది."}}, {"t": "`discount_amount` given on the sale", "a": "r", "why": "Discount in rupees is added up (total discount given), so it is a measure.", "te": {"t": "Sale మీద ఇచ్చిన `discount_amount`", "why": "రూపాయల్లో ఉన్న discount ని add చేస్తారు (మొత్తం ఎంత discount ఇచ్చారు), అందుకే ఇది measure."}}, {"t": "`customer_name`", "a": "l", "why": "A name tells you who bought. It is text that describes the customer, so it is a customer dimension attribute.", "te": {"t": "`customer_name`", "why": "Name, ఎవరు కొన్నారో చెబుతుంది. ఇది customer గురించి చెప్పే text, అందుకే customer dimension attribute."}}, {"t": "Table with one row per product", "a": "l", "why": "It lists each product once with its details (name, brand, category). That is the product dimension.", "te": {"t": "ప్రతి product కి ఒక row ఉన్న table", "why": "ప్రతి product ని దాని details తో (name, brand, category) ఒక్కసారి చూపిస్తుంది. అదే product dimension."}}, {"t": "`tax_amount` charged", "a": "r", "why": "Tax in rupees is added up (total tax collected), so it is a measure.", "te": {"t": "వేసిన `tax_amount`", "why": "రూపాయల్లో ఉన్న tax ని add చేస్తారు (మొత్తం ఎంత tax వచ్చింది), అందుకే ఇది measure."}}, {"t": "`store_name`", "a": "l", "why": "It tells you where the sale happened, so it belongs in the store dimension.", "te": {"t": "`store_name`", "why": "Sale ఎక్కడ జరిగిందో చెబుతుంది, అందుకే store dimension లో ఉంటుంది."}}, {"t": "Table with one row per calendar day", "a": "l", "why": "One row per day, with month, weekday and holiday columns: that is the date dimension.", "te": {"t": "ప్రతి calendar day కి ఒక row ఉన్న table", "why": "రోజుకి ఒక row, month, weekday, holiday columns తో: అదే date dimension."}}, {"t": "Table with one row per UPI payment received", "a": "r", "why": "Each row is an event (a payment happened) with an amount to add up, so it is a fact table.", "te": {"t": "వచ్చిన ప్రతి UPI payment కి ఒక row ఉన్న table", "why": "ప్రతి row ఒక event (ఒక payment జరిగింది), add చేయగల amount ఉంటుంది. అందుకే ఇది fact table."}}, {"t": "`product_brand`", "a": "l", "why": "Brand describes the product and you filter or group by it, so it sits in the product dimension.", "te": {"t": "`product_brand`", "why": "Brand, product గురించి చెబుతుంది; దానితో filter లేదా group చేస్తారు. అందుకే product dimension లో ఉంటుంది."}}, {"t": "`profit_amount` on the sale", "a": "r", "why": "Profit in rupees is added up across sales (total profit), so it is a measure.", "te": {"t": "Sale మీద `profit_amount`", "why": "రూపాయల్లో ఉన్న profit ని అన్ని sales కి add చేస్తారు (మొత్తం profit), అందుకే ఇది measure."}}, {"t": "Table with one row per customer", "a": "l", "why": "It lists each customer once with details like name and city. That is the customer dimension.", "te": {"t": "ప్రతి customer కి ఒక row ఉన్న table", "why": "ప్రతి customer ని name, city లాంటి details తో ఒక్కసారి చూపిస్తుంది. అదే customer dimension."}}]}
];
